function applyUniversalPolandLocalizationPacks() {
  for (const locale of SUPPORTED_LOCALES) {
    if (locale === 'en') continue;
    const country = COUNTRY_NAMES[locale]?.Poland || EXPANDED_COUNTRY_NAMES[locale]?.Poland || 'Poland';
    const copy = resolveCountryCopy(locale, country);
    const baseMap = buildExpandedPolandMap(locale);
    const textOnlyMap = buildExpandedPolandTextOnlyMap(locale);
    SECTION_LABELS[locale] = { ...(SECTION_LABELS[locale] || {}), ...baseMap };
    COMMON_LABELS[locale] = { ...(COMMON_LABELS[locale] || {}), ...baseMap };
    COUNTRY_PAGE_LABELS[locale] = { ...(COUNTRY_PAGE_LABELS[locale] || {}), ...baseMap, ...textOnlyMap };
    COUNTRY_PAGE_RICH_LABELS[locale] = { ...(COUNTRY_PAGE_RICH_LABELS[locale] || {}), ...baseMap, ...textOnlyMap };
  }
}

function applyExpandedLocalePacks() {
  for (const [locale, names] of Object.entries(EXPANDED_COUNTRY_NAMES)) {
    COUNTRY_NAMES[locale] = names;
    const copy = resolveCountryCopy(locale, names.Poland || 'Poland');
    UI[locale] = {
      ...EN_UI_BASE,
      ...(EXPANDED_UI_LABELS[locale] || {}),
      countryShape: copy.countryShape,
      location: copy.location,
      staticCompiled: copy.staticCompiled,
      findCountryTool: copy.findTool,
      clear: copy.clear,
      clearCountryToolSearch: copy.clear,
      searchCountryWorkbenches: copy.searchHint,
      officialAdministrativeOutline: copy.officialAdministrativeOutline,
      geographicPosition: copy.geographicPositionEurope,
      shapeOutline: copy.shapeCaption,
      mapHighlight: copy.mapCaption
    };
    const baseMap = buildExpandedPolandMap(locale);
    const textOnlyMap = buildExpandedPolandTextOnlyMap(locale);
    SECTION_LABELS[locale] = { ...(SECTION_LABELS[locale] || {}), ...baseMap };
    COMMON_LABELS[locale] = { ...(COMMON_LABELS[locale] || {}), ...baseMap };
    COUNTRY_PAGE_LABELS[locale] = { ...(COUNTRY_PAGE_LABELS[locale] || {}), ...baseMap, ...textOnlyMap };
    COUNTRY_PAGE_RICH_LABELS[locale] = { ...(COUNTRY_PAGE_RICH_LABELS[locale] || {}), ...baseMap, ...textOnlyMap };
  }
}

function applyCountryProtectedValueTranslations(content, locale) {
  const map = COUNTRY_PAGE_RICH_LABELS[locale] || {};
  const values = ['Comma (,)', 'Space ( ) or Dot (.)'];
  let next = content;
  for (const value of values) {
    if (!map[value]) continue;
    next = replaceAllLiteral(next, '<code>' + value + '</code>', '<code>' + map[value] + '</code>');
    next = replaceAllLiteral(next, 'data-copy-value="' + value + '"', 'data-copy-value="' + map[value] + '"');
  }
  const countryName = COUNTRY_NAMES[locale]?.Poland;
  if (countryName) {
    next = replaceAllLiteral(next, '00-001 Warszawa\nPoland</code></pre>', '00-001 Warszawa\n' + countryName + '</code></pre>');
  }
  return next;
}
